        "code": "#!/usr/bin/env python3\n\nTABLE = bytes.fromhex(\n    \"30 be cd e9 1b 0b 32 d2 75 1f cc 41 19 af 4c e9 \"\n    \"8c 40 ab d2 6d 3a 9e 01 6a d4\"\n)\n\n\ndef main():\n    state = -0x5B\n    key = []\n    for index, encoded in enumerate(TABLE):\n        # The previous loop result remains in EAX and feeds the next round.\n        state = (0x37 + 0x11 * index + 31 * state) & 0xFF\n        rotated = ((state << 3) | (state >> 5)) & 0xFF\n        state = rotated ^ encoded ^ 0xC7\n        key.append(state)\n    license_key = bytes(key).decode(\"ascii\")\n    assert len(license_key) == 26\n    print(license_key)\n\n\nif __name__ == \"__main__\":\n    main()\n"
