        "code": "#!/usr/bin/env python3\nfrom pathlib import Path\n\n\ndef main():\n    blob = Path(__file__).with_name(\"chall\").read_bytes()\n    code = blob[0x2080:0x2514]\n    states = {(bytes(256), b\"\")}\n\n    # Byte 7 is an OR-accumulator checked against zero after execution.\n    for pc in range(0, len(code), 4):\n        op, a, b, _ = code[pc:pc + 4]\n        next_states = set()\n        for old, text in states:\n            for value in range(256) if op == 8 else (None,):\n                work = bytearray(old)\n                result = text\n                if op in (0, 1):\n                    work[a] = b\n                elif op == 2:\n                    work[a] = work[b]\n                elif op == 3:\n                    work[a] = (work[a] + work[b]) & 0xff\n                elif op == 4:\n                    work[a] = (work[a] - work[b]) & 0xff\n                elif op == 5:\n                    work[a] ^= work[b]\n                elif op == 6:\n                    work[a] = (work[a] + b) & 0xff\n                elif op == 7:\n                    work[a] ^= b\n                elif op == 8:\n                    work[a] = value\n                    result += bytes((value,))\n                elif op == 9:\n                    pass\n                elif op == 10:\n                    work[a] |= work[b]\n                else:\n                    raise ValueError(f\"unexpected opcode {op} at {pc:#x}\")\n                if work[7] == 0:\n                    next_states.add((bytes(work), result))\n        states = next_states\n        assert states, f\"no valid state at bytecode offset {pc:#x}\"\n\n    assert len(states) == 1\n    flag = next(iter(states))[1]\n    assert len(flag) == 55\n    print(flag.decode(\"ascii\"))\n\n\nif __name__ == \"__main__\":\n    main()\n"
